// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 japes98
//! The MIDI output's capture (docs/HARNESS.md, "MIDI output"): the bytes
//! with their times (`midi-out.csv`) and the messages they make
//! (`midi-out.txt`), decoded by the MIDI 1.0 rules: running status, real-time
//! bytes anywhere, system exclusive up to F7.

/// `ms` with three decimals, from microseconds.
fn ms(us: u64) -> String {
    format!("{}.{:03}", us / 1000, us % 1000)
}

/// `ms,byte` and one row per byte: its time (when its stop bit ended) and
/// the byte as two hex digits.
pub fn csv(sent: &[(u64, u8)]) -> String {
    let mut s = String::from("ms,byte\n");
    for (us, b) in sent {
        s.push_str(&format!("{},{:02x}\n", ms(*us), b));
    }
    s
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect::<Vec<_>>().join(" ")
}

/// Data bytes a status byte takes (channel and system common messages).
fn data_len(status: u8) -> usize {
    match status & 0xf0 {
        0xc0 | 0xd0 => 1,
        0x80..=0xe0 => 2,
        _ => match status {
            0xf1 | 0xf3 => 1,
            0xf2 => 2,
            _ => 0,
        },
    }
}

fn channel_message(msg: &[u8]) -> String {
    let ch = (msg[0] & 0x0f) + 1;
    let (a, b) = (msg[1], msg.get(2).copied().unwrap_or(0));
    match msg[0] & 0xf0 {
        0x80 => format!("note-off ch {ch} key {a} vel {b}"),
        0x90 => format!("note-on ch {ch} key {a} vel {b}"),
        0xa0 => format!("poly-pressure ch {ch} key {a} value {b}"),
        0xb0 => format!("control-change ch {ch} ctrl {a} value {b}"),
        0xc0 => format!("program-change ch {ch} program {a}"),
        0xd0 => format!("channel-pressure ch {ch} value {a}"),
        _ => format!("pitch-bend ch {ch} value {}", (b as u32) << 7 | a as u32),
    }
}

fn system_message(msg: &[u8]) -> String {
    match msg[0] {
        0xf1 => format!("mtc-quarter-frame {:02x}", msg[1]),
        0xf2 => format!("song-position {}", (msg[2] as u32) << 7 | msg[1] as u32),
        0xf3 => format!("song-select {}", msg[1]),
        0xf6 => "tune-request".into(),
        0xf8 => "clock".into(),
        0xfa => "start".into(),
        0xfb => "continue".into(),
        0xfc => "stop".into(),
        0xfe => "active-sensing".into(),
        0xff => "reset".into(),
        b => format!("undefined {b:02x}"),
    }
}

/// One line per message: the time of its last byte, then the message.
/// Lines also say `(running status)` for a message sent without its
/// status byte, and name what breaks the rules: `stray-data`,
/// `sysex-unterminated`, `incomplete` (at the end).
pub fn decode(sent: &[(u64, u8)]) -> String {
    let mut out = String::new();
    let mut line = |us: u64, text: String| out.push_str(&format!("{} {}\n", ms(us), text));
    let mut running: Option<u8> = None;
    let mut msg: Vec<u8> = Vec::new();
    let mut implied = false;
    let mut sysex: Option<Vec<u8>> = None;
    let mut last_us = 0;
    for &(us, b) in sent {
        // what a byte cuts short ends with the byte before it
        let prev_us = last_us;
        last_us = us;
        if b >= 0xf8 {
            line(us, system_message(&[b]));
            continue;
        }
        if let Some(sx) = sysex.as_mut() {
            if b < 0x80 {
                sx.push(b);
                continue;
            }
            let mut sx = sysex.take().unwrap();
            if b == 0xf7 {
                sx.push(b);
                line(us, format!("sysex {} ({} bytes)", hex(&sx), sx.len()));
                continue;
            }
            line(prev_us, format!("sysex-unterminated {}", hex(&sx)));
        }
        if b >= 0x80 {
            if !msg.is_empty() {
                line(prev_us, format!("incomplete {}", hex(&msg)));
                msg.clear();
            }
            implied = false;
            match b {
                0xf0 => {
                    running = None;
                    sysex = Some(vec![b]);
                    continue;
                }
                0xf7 => {
                    line(us, "stray-data f7".into());
                    continue;
                }
                0xf1..=0xf6 => running = None,
                _ => running = Some(b),
            }
            msg.push(b);
        } else if msg.is_empty() {
            match running {
                Some(s) => {
                    msg.push(s);
                    implied = true;
                }
                None => {
                    line(us, format!("stray-data {b:02x}"));
                    continue;
                }
            }
            msg.push(b);
        } else {
            msg.push(b);
        }
        if msg.len() == 1 + data_len(msg[0]) {
            let text = if msg[0] < 0xf0 { channel_message(&msg) } else { system_message(&msg) };
            line(us, if implied { format!("{text} (running status)") } else { text });
            msg.clear();
            implied = false;
        }
    }
    if let Some(sx) = sysex {
        line(last_us, format!("incomplete {}", hex(&sx)));
    } else if !msg.is_empty() {
        line(last_us, format!("incomplete {}", hex(&msg)));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn at(bytes: &[u8]) -> Vec<(u64, u8)> {
        bytes.iter().enumerate().map(|(i, &b)| (320 * (i as u64 + 1), b)).collect()
    }

    #[test]
    fn csv_has_times_and_hex() {
        assert_eq!(csv(&at(&[0x90, 0x3c])), "ms,byte\n0.320,90\n0.640,3c\n");
    }

    #[test]
    fn channel_messages_and_running_status() {
        let got = decode(&at(&[0x90, 60, 100, 62, 90, 0x80, 60, 0, 0xc1, 5, 0xe0, 0, 64, 0xb2, 7, 127, 0xd0, 3, 0xa0, 60, 9]));
        assert_eq!(got, "\
0.960 note-on ch 1 key 60 vel 100
1.600 note-on ch 1 key 62 vel 90 (running status)
2.560 note-off ch 1 key 60 vel 0
3.200 program-change ch 2 program 5
4.160 pitch-bend ch 1 value 8192
5.120 control-change ch 3 ctrl 7 value 127
5.760 channel-pressure ch 1 value 3
6.720 poly-pressure ch 1 key 60 value 9
");
    }

    #[test]
    fn real_time_inside_a_message_and_system_common() {
        let got = decode(&at(&[0x90, 60, 0xf8, 100, 0xf2, 0x10, 0x01, 61, 0xf6, 0xff]));
        assert_eq!(got, "\
0.960 clock
1.280 note-on ch 1 key 60 vel 100
2.240 song-position 144
2.560 stray-data 3d
2.880 tune-request
3.200 reset
");
    }

    #[test]
    fn sysex() {
        let got = decode(&at(&[0xf0, 0x43, 0x10, 0xf8, 0x01, 0xf7, 0xf0, 0x7d, 0x90, 60, 1, 0xf7]));
        assert_eq!(got, "\
1.280 clock
1.920 sysex f0 43 10 01 f7 (5 bytes)
2.560 sysex-unterminated f0 7d
3.520 note-on ch 1 key 60 vel 1
3.840 stray-data f7
");
    }

    #[test]
    fn incomplete_at_the_end_and_before_a_status() {
        assert_eq!(decode(&at(&[0x90, 60, 0xc0])), "0.640 incomplete 90 3c\n0.960 incomplete c0\n");
        assert_eq!(decode(&at(&[0xf0, 1])), "0.640 incomplete f0 01\n");
        assert_eq!(decode(&[]), "");
    }
}

/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* E-20: MIDI input on UART1 (source 20), the cases E-19 leaves out. The
   handler counts its entries in OUT(10) and acknowledges a receive pending
   (CON0 bit 12) or a timeout (bit 10) without ever latching (bit 7), with
   CON0's set-up bits from OUT(11). The script (scripts/e20-midi-rx-cases.txt)
   sends bytes in each phase; times are TIMER4's, from the start.
     A (0.5 ms): CON0 0x09, the receive interrupt on but not the DMA, a
       16-byte ring, RXCNT 1. At 2 ms: OUT(0) BUF, OUT(1) CON0, OUT(2) the
       entries.
     B (2 ms): the DMA on (CON0 0x69) with RXEADR = RXSADR. At 4 ms: OUT(3)
       CON0, OUT(4) the entries, OUT(5) the ring's first word.
     C (4 ms): a 16-byte ring at RING, RXCNT 2, OTCNT 480 000 (10 ms). At
       7.5 ms: OUT(6) the entries since C began, OUT(7) CON0.
     D (7.5 ms): the ring moved to RING2; at 8.8 ms, two bytes in, RXSADR
       written again with RING2. At 11 ms: OUT(8) the entries since D began.
   OUT(9) marks the end. */
#include "exp.h"

#define IRQ_UART1 20u
#define UT1_CON0 REG(0x12100u)
#define UT1_BUF REG(0x1210cu)
#define UT1_OTCNT REG(0x12110u)
#define UT1_RXSADR REG(0x1211cu)
#define UT1_RXEADR REG(0x12120u)
#define UT1_RXCNT REG(0x12124u)
#define RING 0x01c00200u
#define RING2 0x01c00300u
#define ON (0x01u | 0x08u | 0x20u | 0x40u)

__attribute__((interrupt)) void uart1_isr(void)
{
    u32 con = UT1_CON0;
    OUT(10)++;
    UT1_CON0 = OUT(11) | ((con & 0x4000u) ? 0x1000u : 0u) | ((con & 0x800u) ? 0x400u : 0u);
}

static void until_us(u32 us)
{
    while (TMR_CNT(4) < 24u * us) {
    }
}

static void fill(u32 at)
{
    for (u32 i = 0u; i < 4u; i++) {
        REG(at + 4u * i) = 0xeeeeeeeeu;
    }
}

int main(void)
{
    TMR_CON(4) = 1u;
    fill(RING);
    fill(RING2);
    VECTOR(IRQ_UART1) = (u32)uart1_isr;
    ICFG(IRQ_UART1) |= ICFG_ON(IRQ_UART1, 2u);
    irq_on();

    until_us(500);
    UT1_RXSADR = RING;
    UT1_RXEADR = RING + 16u;
    UT1_RXCNT = 1u;
    OUT(11) = 0x09u;
    UT1_CON0 = 0x09u;
    until_us(2000);
    OUT(0) = UT1_BUF;
    OUT(1) = UT1_CON0;
    OUT(2) = OUT(10);

    UT1_CON0 = 0u;
    UT1_RXEADR = RING;
    OUT(11) = ON;
    UT1_CON0 = ON;
    until_us(4000);
    OUT(3) = UT1_CON0;
    OUT(4) = OUT(10);
    OUT(5) = REG(RING);

    UT1_CON0 = 0u;
    UT1_RXSADR = RING;
    UT1_RXEADR = RING + 16u;
    UT1_RXCNT = 2u;
    UT1_OTCNT = 480000u;
    u32 c0 = OUT(10);
    UT1_CON0 = ON;
    until_us(7500);
    OUT(6) = OUT(10) - c0;
    OUT(7) = UT1_CON0;

    u32 d0 = OUT(10);
    UT1_RXSADR = RING2;
    UT1_RXEADR = RING2 + 16u;
    until_us(8800);
    UT1_RXSADR = RING2;
    until_us(11000);
    OUT(8) = OUT(10) - d0;
    OUT(9) = 0x600dd00eu;
    for (;;) {
    }
}

/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* E-19: MIDI input on UART1 (source 20), received by DMA into a ring.
   OUT(0) is CON0 as read at the start, OUT(1) the ring's first word after
   the bytes the script sends while the UART is off (scripts/e19-midi-rx.txt).
   Then the ring (16 bytes at RING, filled with 0xEE first) is set up with
   RXCNT 4 and OTCNT 48 000 (1 ms of the 48 MHz UART clock), and CON0 turned
   on with the receive and timeout interrupts and the receive DMA. The
   handler counts its entries in OUT(12) and logs four words per entry:
   TIMER4's count, CON0 as read on entry, HRXCNT after a latch (CON0 bit 7),
   and CON0 after the acknowledge (bit 12 for a receive pending, bit 10 for
   a timeout). OUT(13) marks the set-up done. */
#include "exp.h"

#define IRQ_UART1 20u
#define UT1_CON0 REG(0x12100u)
#define UT1_OTCNT REG(0x12110u)
#define UT1_RXSADR REG(0x1211cu)
#define UT1_RXEADR REG(0x12120u)
#define UT1_RXCNT REG(0x12124u)
#define UT1_HRXCNT REG(0x12128u)
#define RING 0x01c00200u
#define ON (0x01u | 0x08u | 0x20u | 0x40u)

__attribute__((interrupt)) void uart1_isr(void)
{
    u32 n = OUT(12)++;
    u32 con = UT1_CON0;
    volatile u32 *e = LOG + 4u * (n & 31u);
    e[0] = TMR_CNT(4);
    e[1] = con;
    UT1_CON0 = ON | 0x80u;
    e[2] = UT1_HRXCNT;
    UT1_CON0 = ON | ((con & 0x4000u) ? 0x1000u : 0u) | ((con & 0x800u) ? 0x400u : 0u);
    e[3] = UT1_CON0;
}

int main(void)
{
    TMR_CON(4) = 1u;
    OUT(0) = UT1_CON0;
    for (u32 i = 0u; i < 4u; i++) {
        REG(RING + 4u * i) = 0xeeeeeeeeu;
    }
    wait_us(2000);
    OUT(1) = REG(RING);
    VECTOR(IRQ_UART1) = (u32)uart1_isr;
    ICFG(IRQ_UART1) |= ICFG_ON(IRQ_UART1, 2u);
    irq_on();
    UT1_RXSADR = RING;
    UT1_RXEADR = RING + 16u;
    UT1_RXCNT = 4u;
    UT1_OTCNT = 48000u;
    UT1_CON0 = ON;
    OUT(13) = 0x600dd00eu;
    for (;;) {
        wait_us(1000);
    }
}

