1	// SPDX-License-Identifier: MIT
2	// SPDX-FileCopyrightText: 2026 japes98
3	//! The MIDI output's capture (docs/HARNESS.md, "MIDI output"): the bytes
4	//! with their times (`midi-out.csv`) and the messages they make
5	//! (`midi-out.txt`), decoded by the MIDI 1.0 rules: running status, real-time
6	//! bytes anywhere, system exclusive up to F7.
7	
8	/// `ms` with three decimals, from microseconds.
9	fn ms(us: u64) -> String {
10	    format!("{}.{:03}", us / 1000, us % 1000)
11	}
12	
13	/// `ms,byte` and one row per byte: its time (when its stop bit ended) and
14	/// the byte as two hex digits.
15	pub fn csv(sent: &[(u64, u8)]) -> String {
16	    let mut s = String::from("ms,byte\n");
17	    for (us, b) in sent {
18	        s.push_str(&format!("{},{:02x}\n", ms(*us), b));
19	    }
20	    s
21	}
22	
23	fn hex(bytes: &[u8]) -> String {
24	    bytes.iter().map(|b| format!("{b:02x}")).collect::<Vec<_>>().join(" ")
25	}
26	
27	/// Data bytes a status byte takes (channel and system common messages).
28	fn data_len(status: u8) -> usize {
29	    match status & 0xf0 {
30	        0xc0 | 0xd0 => 1,
31	        0x80..=0xe0 => 2,
32	        _ => match status {
33	            0xf1 | 0xf3 => 1,
34	            0xf2 => 2,
35	            _ => 0,
36	        },
37	    }
38	}
39	
40	fn channel_message(msg: &[u8]) -> String {
41	    let ch = (msg[0] & 0x0f) + 1;
42	    let (a, b) = (msg[1], msg.get(2).copied().unwrap_or(0));
43	    match msg[0] & 0xf0 {
44	        0x80 => format!("note-off ch {ch} key {a} vel {b}"),
45	        0x90 => format!("note-on ch {ch} key {a} vel {b}"),
46	        0xa0 => format!("poly-pressure ch {ch} key {a} value {b}"),
47	        0xb0 => format!("control-change ch {ch} ctrl {a} value {b}"),
48	        0xc0 => format!("program-change ch {ch} program {a}"),
49	        0xd0 => format!("channel-pressure ch {ch} value {a}"),
50	        _ => format!("pitch-bend ch {ch} value {}", (b as u32) << 7 | a as u32),
51	    }
52	}
53	
54	fn system_message(msg: &[u8]) -> String {
55	    match msg[0] {
56	        0xf1 => format!("mtc-quarter-frame {:02x}", msg[1]),
57	        0xf2 => format!("song-position {}", (msg[2] as u32) << 7 | msg[1] as u32),
58	        0xf3 => format!("song-select {}", msg[1]),
59	        0xf6 => "tune-request".into(),
60	        0xf8 => "clock".into(),
61	        0xfa => "start".into(),
62	        0xfb => "continue".into(),
63	        0xfc => "stop".into(),
64	        0xfe => "active-sensing".into(),
65	        0xff => "reset".into(),
66	        b => format!("undefined {b:02x}"),
67	    }
68	}
69	
70	/// One line per message: the time of its last byte, then the message.
71	/// Lines also say `(running status)` for a message sent without its
72	/// status byte, and name what breaks the rules: `stray-data`,
73	/// `sysex-unterminated`, `incomplete` (at the end).
74	pub fn decode(sent: &[(u64, u8)]) -> String {
75	    let mut out = String::new();
76	    let mut line = |us: u64, text: String| out.push_str(&format!("{} {}\n", ms(us), text));
77	    let mut running: Option<u8> = None;
78	    let mut msg: Vec<u8> = Vec::new();
79	    let mut implied = false;
80	    let mut sysex: Option<Vec<u8>> = None;
81	    let mut last_us = 0;
82	    for &(us, b) in sent {
83	        // what a byte cuts short ends with the byte before it
84	        let prev_us = last_us;
85	        last_us = us;
86	        if b >= 0xf8 {
87	            line(us, system_message(&[b]));
88	            continue;
89	        }
90	        if let Some(sx) = sysex.as_mut() {
91	            if b < 0x80 {
92	                sx.push(b);
93	                continue;
94	            }
95	            let mut sx = sysex.take().unwrap();
96	            if b == 0xf7 {
97	                sx.push(b);
98	                line(us, format!("sysex {} ({} bytes)", hex(&sx), sx.len()));
99	                continue;
100	            }
101	            line(prev_us, format!("sysex-unterminated {}", hex(&sx)));
102	        }
103	        if b >= 0x80 {
104	            if !msg.is_empty() {
105	                line(prev_us, format!("incomplete {}", hex(&msg)));
106	                msg.clear();
107	            }
108	            implied = false;
109	            match b {
110	                0xf0 => {
111	                    running = None;
112	                    sysex = Some(vec![b]);
113	                    continue;
114	                }
115	                0xf7 => {
116	                    line(us, "stray-data f7".into());
117	                    continue;
118	                }
119	                0xf1..=0xf6 => running = None,
120	                _ => running = Some(b),
121	            }
122	            msg.push(b);
123	        } else if msg.is_empty() {
124	            match running {
125	                Some(s) => {
126	                    msg.push(s);
127	                    implied = true;
128	                }
129	                None => {
130	                    line(us, format!("stray-data {b:02x}"));
131	                    continue;
132	                }
133	            }
134	            msg.push(b);
135	        } else {
136	            msg.push(b);
137	        }
138	        if msg.len() == 1 + data_len(msg[0]) {
139	            let text = if msg[0] < 0xf0 { channel_message(&msg) } else { system_message(&msg) };
140	            line(us, if implied { format!("{text} (running status)") } else { text });
141	            msg.clear();
142	            implied = false;
143	        }
144	    }
145	    if let Some(sx) = sysex {
146	        line(last_us, format!("incomplete {}", hex(&sx)));
147	    } else if !msg.is_empty() {
148	        line(last_us, format!("incomplete {}", hex(&msg)));
149	    }
150	    out
151	}
